package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaGradeSevenProductTest {
 @Test public void publicBoundaryFactorsAndEquivalentAnswers(){for(int[]p:new int[][]{{0,1000000},{1000000,0},{1,1000000},{1000000,1},{1000,1000},{999999,1},{1234,567}}){Question q=BoundedWholeProduct.make(p[0],p[1]);q.answers=new String[]{"poison"};q.expression="poison";int value=p[0]*p[1];for(String s:List.of(""+value,value+".0",value+"/1"))assertTrue(new Checker().check(q,List.of(),List.of(s)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(value+1))).status);assertFalse(HelpPlan.forQuestion(q).canTransfer());assertTrue(HelpPlan.forQuestion(q).size()>2);}}
 @Test public void gradeSevenSupplyIsVariedFreshAndKeepsOtherGrades(){var l=GlobalCurriculum.limits("na-nied-primary-2024-v1","mul22",7);assertTrue(BoundedWholeProduct.selected("mul22",l));assertFalse(BoundedWholeProduct.selected("mul22",GlobalCurriculum.limits("na-nied-primary-2024-v1","mul22",6)));Generator g=new Generator(new Random(307));List<String>recent=new ArrayList<>();Set<Integer>lengths=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next("mul22",recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertEquals(BoundedWholeProduct.KIND,q.kind);assertTrue(l.allows(q));for(String s:q.prompt.split(" × "))lengths.add(s.length());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertTrue(lengths.containsAll(Set.of(1,2,3,4,5,6)));}
}
